import{_ as o,c as a,o as i,a2 as s}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Troubleshooting (Gomoku on macOS)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1780466351000}'),t={name:"guide/troubleshooting.md"};function r(n,e,l,p,c,d){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting-gomoku-on-macos" tabindex="-1">Troubleshooting (Gomoku on macOS) <a class="header-anchor" href="#troubleshooting-gomoku-on-macos" aria-label="Permalink to &quot;Troubleshooting (Gomoku on macOS)&quot;">​</a></h1><p>This page collects common problems for macOS users and how to resolve them.</p><h2 id="application-won-t-start-or-crashes-on-launch" tabindex="-1">Application won&#39;t start or crashes on launch <a class="header-anchor" href="#application-won-t-start-or-crashes-on-launch" aria-label="Permalink to &quot;Application won&#39;t start or crashes on launch&quot;">​</a></h2><p>Symptoms: Gomoku does not open, crashes immediately, or shows an unexpected error.</p><p>Steps to try:</p><ol><li>Ensure your macOS version meets the minimum requirements (Monterey 12+ recommended).</li><li>Quit and relaunch the app.</li><li>Reboot your Mac.</li><li>If the app was downloaded from Releases, try downloading a newer build or the signed/notarized build.</li><li>If problems persist, collect logs (see below) and open an issue on the project repository.</li></ol><h2 id="lan-matchmaking-issues" tabindex="-1">LAN / Matchmaking issues <a class="header-anchor" href="#lan-matchmaking-issues" aria-label="Permalink to &quot;LAN / Matchmaking issues&quot;">​</a></h2><p>Symptoms: You cannot discover or join LAN games.</p><p>Checklist:</p><ol><li>Confirm <strong>Local Network</strong> permission is granted (System Settings → Privacy &amp; Security → Local Network).</li><li>Ensure all devices are connected to the same Wi‑Fi network; router client/AP isolation will block discovery.</li><li>Disable or configure firewall rules to allow Gomoku traffic.</li></ol><h2 id="saving-opening-game-records-sgf-fails" tabindex="-1">Saving / Opening game records (SGF) fails <a class="header-anchor" href="#saving-opening-game-records-sgf-fails" aria-label="Permalink to &quot;Saving / Opening game records (SGF) fails&quot;">​</a></h2><p>Symptoms: Export or import of <code>.sgf</code> files fails or prompts for permission.</p><p>Fixes:</p><ol><li>Check <strong>Files and Folders</strong> permission (System Settings → Privacy &amp; Security → Files and Folders).</li><li>Try saving to <code>Documents</code> or <code>Downloads</code> first to verify write access.</li><li>Ensure the target path is not on an external drive with restrictive permissions.</li></ol><h2 id="permission-related-issues" tabindex="-1">Permission-related issues <a class="header-anchor" href="#permission-related-issues" aria-label="Permalink to &quot;Permission-related issues&quot;">​</a></h2><p>If a feature prompts for permission but doesn&#39;t work after granting it:</p><ol><li>Quit the app and reopen it after granting the permission.</li><li>If needed, reset the permission prompt with <code>tccutil</code> (see the Permissions guide).</li></ol><h2 id="performance-issues" tabindex="-1">Performance issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to &quot;Performance issues&quot;">​</a></h2><p>If the game is laggy or slow:</p><ol><li>Close other heavy applications.</li><li>Prefer a wired connection for LAN play when possible.</li><li>Reduce background processes that consume CPU or network bandwidth.</li></ol><h2 id="view-logs" tabindex="-1">View logs <a class="header-anchor" href="#view-logs" aria-label="Permalink to &quot;View logs&quot;">​</a></h2><p>To troubleshoot crashes or network issues, application logs are the most useful artifact. In sandboxed (App Store) builds, check:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.gomoku/Data/Library/Logs/gomoku/gomoku.log</span></span></code></pre></div><p>When running a development build, logs may be in the project directory (<code>./src-tauri/gomoku.log</code>) or printed to the console.</p><h2 id="resetting-the-app" tabindex="-1">Resetting the app <a class="header-anchor" href="#resetting-the-app" aria-label="Permalink to &quot;Resetting the app&quot;">​</a></h2><p>To reset settings and clear local data:</p><ol><li>Quit Gomoku</li><li>Remove the container or support data (be careful—this deletes saved games and settings):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.gomoku</span></span></code></pre></div><ol start="3"><li>Reopen Gomoku and reconfigure.</li></ol><h2 id="report-an-issue" tabindex="-1">Report an issue <a class="header-anchor" href="#report-an-issue" aria-label="Permalink to &quot;Report an issue&quot;">​</a></h2><p>When opening an issue, include:</p><ul><li>macOS version (Apple menu → About This Mac)</li><li>Gomoku version (Gomoku → About Gomoku)</li><li>Steps to reproduce</li><li>Logs (attach <code>gomoku.log</code> if available)</li></ul><p>This helps maintainers identify and fix the problem faster.</p>',33)])])}const m=o(t,[["render",r]]);export{u as __pageData,m as default};
